WITH base AS (WITH sat AS (SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_pack_status' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_pack_status UNION ALL SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_pack_test' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_pack_test UNION ALL SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_passport_data' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_passport_data UNION ALL SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_diagnostic_result' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_diagnostic_result UNION ALL SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_service_status' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_service_status UNION ALL SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_campaign_status' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_campaign_status UNION ALL SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_claim_status' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_claim_status UNION ALL SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_recall_status' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_recall_status UNION ALL SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_shipment_status' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_shipment_status UNION ALL SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_second_life_status' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_second_life_status UNION ALL SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_recycling_status' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_recycling_status UNION ALL SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_certificate_status' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_certificate_status UNION ALL SELECT satellite_id source_record_id,parent_key,load_dts,effective_from,state_code,related_refs_json object_refs,actor_code actor,'sat_incident_status' source_table,is_correction,hashdiff,ROW_NUMBER() OVER(PARTITION BY parent_key,hashdiff ORDER BY is_correction,load_dts) duplicate_no FROM sat_incident_status), sat_mapped AS (SELECT source_record_id,parent_key,effective_from timestamp,state_code,object_refs,actor,source_table,CASE state_code WHEN 'BV001' THEN 'Cell Batch Produced' WHEN 'BV002' THEN 'Cell Batch Released' WHEN 'BV003' THEN 'Module Assembled' WHEN 'BV004' THEN 'Module Tested' WHEN 'BV005' THEN 'Module Failed Test' WHEN 'BV006' THEN 'Battery Pack Assembled' WHEN 'BV007' THEN 'Battery Pack Tested' WHEN 'BV008' THEN 'Battery Pack Passed Test' WHEN 'BV009' THEN 'Battery Pack Failed Test' WHEN 'BV010' THEN 'Battery Passport Issued' WHEN 'BV011' THEN 'Battery Passport Corrected' WHEN 'BV012' THEN 'Battery Installed in Vehicle' WHEN 'BV013' THEN 'Vehicle Delivered' WHEN 'BV014' THEN 'Ownership Transferred' WHEN 'BV015' THEN 'Lease Started' WHEN 'BV016' THEN 'Lease Ended' WHEN 'BV017' THEN 'Battery Removed from Vehicle' WHEN 'BV018' THEN 'Telemetry Anomaly Detected' WHEN 'BV019' THEN 'Diagnostic Scheduled' WHEN 'BV020' THEN 'Diagnostic Run' WHEN 'BV021' THEN 'State of Health Assessed' WHEN 'BV022' THEN 'Service Order Opened' WHEN 'BV023' THEN 'Service Started' WHEN 'BV024' THEN 'Module Replacement Ordered' WHEN 'BV025' THEN 'Module Replaced' WHEN 'BV026' THEN 'Service Completed' WHEN 'BV027' THEN 'Firmware Campaign Assigned' WHEN 'BV028' THEN 'Firmware Downloaded' WHEN 'BV029' THEN 'Firmware Installed' WHEN 'BV030' THEN 'Firmware Installation Failed' WHEN 'BV031' THEN 'Firmware Rolled Back' WHEN 'BV032' THEN 'Warranty Claim Opened' WHEN 'BV033' THEN 'Warranty Claim Approved' WHEN 'BV034' THEN 'Warranty Claim Denied' WHEN 'BV035' THEN 'Recall Campaign Announced' WHEN 'BV036' THEN 'Battery Matched to Recall' WHEN 'BV037' THEN 'Recall Notification Sent' WHEN 'BV038' THEN 'Recall Notification Acknowledged' WHEN 'BV039' THEN 'Recall Service Completed' WHEN 'BV040' THEN 'Transport Booked' WHEN 'BV041' THEN 'Shipment Dispatched' WHEN 'BV042' THEN 'Shipment Received' WHEN 'BV043' THEN 'Battery Quarantined' WHEN 'BV044' THEN 'Battery Released from Quarantine' WHEN 'BV045' THEN 'Second-Life Assessment Started' WHEN 'BV046' THEN 'Second-Life Assessment Passed' WHEN 'BV047' THEN 'Second-Life Assessment Failed' WHEN 'BV048' THEN 'Battery Reconfigured' WHEN 'BV049' THEN 'Second-Life System Commissioned' WHEN 'BV050' THEN 'Second-Life System Decommissioned' WHEN 'BV051' THEN 'Recycling Order Created' WHEN 'BV052' THEN 'Battery Dismantled' WHEN 'BV053' THEN 'Material Batch Recovered' WHEN 'BV054' THEN 'Material Batch Certified' WHEN 'BV055' THEN 'Compliance Certificate Revoked' WHEN 'BV056' THEN 'Compliance Certificate Reissued' WHEN 'BV057' THEN 'Incident Reported' WHEN 'BV058' THEN 'Incident Investigation Started' WHEN 'BV059' THEN 'Incident Closed' WHEN 'BV060' THEN 'Lifecycle Closed' END activity FROM sat WHERE is_correction=0 AND duplicate_no=1), ledger AS (SELECT j.journal_id source_record_id,e.asset_hub_key parent_key,j.effective_at timestamp,j.movement_code state_code,j.related_refs_json object_refs,j.actor_code actor,'asset_journal' source_table,CASE j.movement_code WHEN 'BV001' THEN 'Cell Batch Produced' WHEN 'BV002' THEN 'Cell Batch Released' WHEN 'BV003' THEN 'Module Assembled' WHEN 'BV004' THEN 'Module Tested' WHEN 'BV005' THEN 'Module Failed Test' WHEN 'BV006' THEN 'Battery Pack Assembled' WHEN 'BV007' THEN 'Battery Pack Tested' WHEN 'BV008' THEN 'Battery Pack Passed Test' WHEN 'BV009' THEN 'Battery Pack Failed Test' WHEN 'BV010' THEN 'Battery Passport Issued' WHEN 'BV011' THEN 'Battery Passport Corrected' WHEN 'BV012' THEN 'Battery Installed in Vehicle' WHEN 'BV013' THEN 'Vehicle Delivered' WHEN 'BV014' THEN 'Ownership Transferred' WHEN 'BV015' THEN 'Lease Started' WHEN 'BV016' THEN 'Lease Ended' WHEN 'BV017' THEN 'Battery Removed from Vehicle' WHEN 'BV018' THEN 'Telemetry Anomaly Detected' WHEN 'BV019' THEN 'Diagnostic Scheduled' WHEN 'BV020' THEN 'Diagnostic Run' WHEN 'BV021' THEN 'State of Health Assessed' WHEN 'BV022' THEN 'Service Order Opened' WHEN 'BV023' THEN 'Service Started' WHEN 'BV024' THEN 'Module Replacement Ordered' WHEN 'BV025' THEN 'Module Replaced' WHEN 'BV026' THEN 'Service Completed' WHEN 'BV027' THEN 'Firmware Campaign Assigned' WHEN 'BV028' THEN 'Firmware Downloaded' WHEN 'BV029' THEN 'Firmware Installed' WHEN 'BV030' THEN 'Firmware Installation Failed' WHEN 'BV031' THEN 'Firmware Rolled Back' WHEN 'BV032' THEN 'Warranty Claim Opened' WHEN 'BV033' THEN 'Warranty Claim Approved' WHEN 'BV034' THEN 'Warranty Claim Denied' WHEN 'BV035' THEN 'Recall Campaign Announced' WHEN 'BV036' THEN 'Battery Matched to Recall' WHEN 'BV037' THEN 'Recall Notification Sent' WHEN 'BV038' THEN 'Recall Notification Acknowledged' WHEN 'BV039' THEN 'Recall Service Completed' WHEN 'BV040' THEN 'Transport Booked' WHEN 'BV041' THEN 'Shipment Dispatched' WHEN 'BV042' THEN 'Shipment Received' WHEN 'BV043' THEN 'Battery Quarantined' WHEN 'BV044' THEN 'Battery Released from Quarantine' WHEN 'BV045' THEN 'Second-Life Assessment Started' WHEN 'BV046' THEN 'Second-Life Assessment Passed' WHEN 'BV047' THEN 'Second-Life Assessment Failed' WHEN 'BV048' THEN 'Battery Reconfigured' WHEN 'BV049' THEN 'Second-Life System Commissioned' WHEN 'BV050' THEN 'Second-Life System Decommissioned' WHEN 'BV051' THEN 'Recycling Order Created' WHEN 'BV052' THEN 'Battery Dismantled' WHEN 'BV053' THEN 'Material Batch Recovered' WHEN 'BV054' THEN 'Material Batch Certified' WHEN 'BV055' THEN 'Compliance Certificate Revoked' WHEN 'BV056' THEN 'Compliance Certificate Reissued' WHEN 'BV057' THEN 'Incident Reported' WHEN 'BV058' THEN 'Incident Investigation Started' WHEN 'BV059' THEN 'Incident Closed' WHEN 'BV060' THEN 'Lifecycle Closed' END activity FROM asset_journal j JOIN asset_ledger_entry e ON e.journal_id=j.journal_id GROUP BY j.journal_id HAVING SUM(CASE e.direction WHEN 'DEBIT' THEN e.quantity ELSE -e.quantity END)=0), all_events AS (SELECT * FROM sat_mapped UNION ALL SELECT * FROM ledger) SELECT h.hub_key case_id,activity,timestamp,source_table,source_record_id,actor,object_refs FROM all_events e JOIN hub_battery_pack h ON h.hub_key=e.parent_key WHERE activity IS NOT NULL ORDER BY case_id,timestamp,source_record_id), selected AS (SELECT DISTINCT case_id FROM base WHERE json_array_length(object_refs)>=3) SELECT base.*,CASE WHEN json_array_length(object_refs)>=3 THEN 1 ELSE 0 END is_multi_object_event FROM base JOIN selected USING(case_id) ORDER BY case_id,timestamp,source_record_id;
